CH = dict(num=6, title="Materials Around Us", theme="Properties of materials, classification, matter, mass and volume",
 intro="Ghulan and Sheeta's teacher Madam Vidya makes the class look at everyday objects: how they look, feel and differ. The chapter shows that objects are made of **materials**, that materials are chosen for their **properties**, and that they can be **classified** on appearance, hardness, transparency, solubility, mass and volume. Anything with mass and volume is **matter**.",
 big_questions=["What are objects made of and why are particular materials chosen?", "How can materials be classified?", "What properties do all materials share?", "What is matter?"],
 blocks=[
 ("h2", "6.1 Observing Objects Around Us"),
 ("note", "DEFINITION", "Any substance used to make an object is a **material** (paper, wood, cloth, glass, metal, plastic, clay etc.)."),
 ("ul", ["An object may be made of one material or of **several** (a pen: plastic, metal, ink); the same material can make many objects, and one object can be made from different materials.",
  "**Pottery in India:** earliest pottery is 7,000–8,000 years old (Lahuradewa in the Ganga plains, Mehrgarh in Baluchistan). From about 4000 BCE wheel-turned pots, coloured slips and painted designs developed. Harappan (Sindhu-Sarasvati, 2600–1900 BCE) pottery has bright red surface with black geometric and animal designs. Clay was cleaned, sieved, kneaded, wheel-turned and baked in kilns; **baked clay is terracotta**. Large jars are displayed in the National Museum, New Delhi."]),
 ("h2", "6.2 How to Group Materials?"),
 ("note", "DEFINITION", "Arranging objects into groups on the basis of a common property is **classification**."),
 ("ul", ["Objects can be grouped by shape, colour, hardness, shine or material.", "A material is chosen according to its **properties and the purpose** of the object: a tumbler must hold water, so paper-like cloth is unsuitable; cloth is not used for cooking utensils.", "Activity 6.4 (balls): tennis, cricket and hand-exercise balls of the same size are dropped from a fixed height; bounce differs — balls are made of specific materials for specific games.", "Classification is used in kitchens, grocer shops and chemist shops to find things easily."]),
 ("h2", "6.3 Properties of Materials"),
 ("h3", "6.3.1 Appearance: lustrous and non-lustrous"),
 ("table", ["Type", "Meaning", "Examples"],
  [["**Lustrous**", "Shiny surface", "Metals — iron, copper, zinc, aluminium, gold"],
   ["**Non-lustrous**", "No shiny surface", "Paper, wood, rubber, jute"]]),
 ("ul", ["Some metals lose lustre due to **air and moisture**, so lustre shows on freshly cut surfaces.", "Not all lustrous things are metals: polishing or coating with plastic/wax can make a surface shine ('all that glitters is not gold')."]),
 ("h3", "6.3.2 Hard and soft"),
 ("p", "Materials difficult to compress or scratch are **hard** (stone, iron, brick); those easily compressed or scratched are **soft** (eraser, sponge, candle). Hardness is **relative**: rubber is harder than sponge but softer than iron. Test by scratching with a metal key."),
 ("h3", "6.3.3 Transparency"),
 ("table", ["Type", "Meaning", "Examples"],
  [["**Transparent**", "Objects seen **clearly** through it", "Glass, water, air, cellophane, window glass"],
   ["**Translucent**", "Objects seen **but not clearly**", "Butter paper, frosted glass"],
   ["**Opaque**", "Objects **cannot be seen** through it", "Wood, cardboard, metals, wall, tree"]]),
 ("h3", "6.3.4 Solubility in water"),
 ("ul", ["**Soluble** — completely disappears (dissolves) when stirred in water: sugar, salt.",
  "**Insoluble** — does not mix or disappear: chalk powder, sand, sawdust.",
  "Water is vital to the body as it dissolves many materials.",
  "**ORS** (Oral Rehydration Solution) for dehydration: six teaspoons of sugar and half a teaspoon of salt in one litre of boiled and cooled water.",
  "Some liquids mix with water completely; some (oil) form a separate layer. Some gases dissolve: **oxygen dissolves in water**, which is essential for aquatic life."]),
 ("h3", "6.3.5 Heavy and light — mass"),
 ("p", "Three identical cups half-filled with water, sand and pebbles are weighed on a balance; the heavier has **more mass**. Mass is the property measuring how heavy or light something is (in everyday language called 'weight')."),
 ("h3", "6.3.6 Space and volume"),
 ("p", "Bags on seats leave no room to sit; the same tumbler holds half or full water depending on the amount. The **space occupied** by a material is its **volume**. Bottles marked 1 L, 500 mL show volume."),
 ("h2", "6.4 What Is Matter?"),
 ("note", "DEFINITION", "**Matter** is anything that has **mass** and occupies **space (volume)**. Mass and volume are the two properties possessed by all materials."),
 ("table", ["Quantity", "Units", "How to write"],
  [["Mass", "gram (g), kilogram (kg); SI unit is **kg**", "7 kg (not 7 kgs); no full stop; space between number and unit"],
   ["Volume", "litre (L), millilitre (mL); SI unit is **cubic metre (m<sup>3</sup>)**", "500 mL, 2 m<sup>3</sup>; 1 m<sup>3</sup> = 1000 L"]]),
 ("p", "Water, sand, pebbles and a cup are all matter. Materials are the types of matter used to make objects. Air is also matter (it has mass and occupies space)."),
 ("h3", "Ayurveda's classification"),
 ("p", "Ayurveda describes all physical matter, living things and food using **20 properties (guna)** in **ten opposite pairs**:"),
 ("table", ["Property", "Opposite"],
  [["guru (heavy)", "laghu (light)"], ["manda (slow)", "tikshna (quick)"], ["hima (cold)", "ushna (hot)"], ["snigdha (unctuous)", "ruksha (dry)"], ["shlakshna (smooth)", "khara (rough)"], ["sandra (solid)", "drava (liquid)"], ["mridu (soft)", "kathina (hard)"], ["sthira (stable)", "khala (moving)"], ["sukshma (subtle/small)", "sthula (big)"], ["vishada (non-slimy)", "picchhila (slimy)"]]),
 ("h2", "6.5 Likely Exam Questions"),
 ("qa", [("What is a material? Give examples.", "Any substance used to make an object, e.g. wood, glass, metal, clay."),
  ("What is classification and why is it done?", "Arranging objects into groups on common properties; it helps study and find them easily."),
  ("What decides the choice of material for an object?", "Its properties and the purpose of the object."),
  ("Define lustre. Are all shiny materials metals?", "Shiny appearance; no, polished or coated non-metals may shine."),
  ("Differentiate transparent, translucent and opaque.", "Clear view, unclear view, no view through; glass, butter paper, wood."),
  ("What are soluble and insoluble materials?", "Dissolve completely in water (sugar, salt) and do not dissolve (sand, chalk)."),
  ("Why is hardness called a relative property?", "A material may be harder than one and softer than another, e.g. rubber."),
  ("What is matter?", "Anything that has mass and occupies space."),
  ("Give the units of mass and volume.", "kg and g; m3, L and mL."),
  ("How is ORS prepared at home?", "Six teaspoons of sugar and half a teaspoon salt in one litre boiled and cooled water."),
  ("Why do shops use transparent containers?", "Contents can be seen without opening them."),
  ("Why is dissolved oxygen important?", "Aquatic plants and animals need it to survive.")]),
 ],
 takeaways=["Objects are made from materials chosen for their properties and purpose.",
  "Classification groups materials by similarities and differences.",
  "Materials may be lustrous/non-lustrous, hard/soft, transparent/translucent/opaque, soluble/insoluble.",
  "Mass measures how heavy a material is; volume is the space it occupies.",
  "Anything having mass and volume is matter.",
  "SI units: kg for mass, m<sup>3</sup> for volume (L and mL are commonly used)."])
